-- MySQL 8.4. Import into a NEW database. No existing data is removed.
CREATE TABLE Location (
 Location_ID INT PRIMARY KEY, Location_Name VARCHAR(100) NOT NULL,
 Location_Type VARCHAR(40) NOT NULL, Status ENUM('Active','Inactive') NOT NULL, Peak_Hours VARCHAR(11)
) ENGINE=InnoDB;
CREATE TABLE Counter (
 Counter_ID INT PRIMARY KEY, Counter_Name VARCHAR(100) NOT NULL, Service_Type VARCHAR(60) NOT NULL,
 Open_Time CHAR(5) NOT NULL, Close_Time CHAR(5) NOT NULL, Queue_Limit INT NOT NULL,
 Location_ID INT NOT NULL,
 CONSTRAINT fk_counter_location FOREIGN KEY (Location_ID) REFERENCES Location(Location_ID),
 CONSTRAINT ck_queue_limit CHECK (Queue_Limit > 0)
) ENGINE=InnoDB;
CREATE TABLE Visitor (
 Visitor_ID INT PRIMARY KEY, First_Name VARCHAR(80) NOT NULL, Last_Name VARCHAR(80) NOT NULL,
 Department VARCHAR(40), ID_Number VARCHAR(40) NOT NULL UNIQUE, Visitor_Type VARCHAR(20), Entry_ID INT NULL
) ENGINE=InnoDB;
CREATE TABLE Queue_Entry (
 Entry_ID INT AUTO_INCREMENT PRIMARY KEY, Visitor_ID INT NOT NULL, Counter_ID INT NOT NULL,
 Entry_Date DATE NOT NULL, Arrival_Time CHAR(5) NOT NULL,
 Status ENUM('Waiting','Calling','Served','Left') NOT NULL DEFAULT 'Waiting', Wait_Minutes INT NOT NULL DEFAULT 0,
 Active_Visitor INT GENERATED ALWAYS AS (CASE WHEN Status IN ('Waiting','Calling') THEN Visitor_ID ELSE NULL END) STORED,
 Calling_Counter INT GENERATED ALWAYS AS (CASE WHEN Status='Calling' THEN Counter_ID ELSE NULL END) STORED,
 CONSTRAINT fk_entry_visitor FOREIGN KEY (Visitor_ID) REFERENCES Visitor(Visitor_ID),
 CONSTRAINT fk_entry_counter FOREIGN KEY (Counter_ID) REFERENCES Counter(Counter_ID),
 CONSTRAINT ck_wait CHECK (Wait_Minutes >= 0),
 UNIQUE KEY uq_active_ticket (Counter_ID, Entry_Date, Active_Visitor),
 UNIQUE KEY uq_calling_counter (Entry_Date, Calling_Counter),
 INDEX ix_queue_board (Counter_ID, Entry_Date, Status, Entry_ID)
) ENGINE=InnoDB AUTO_INCREMENT=2001;
CREATE TABLE Prediction (
 Prediction_ID INT AUTO_INCREMENT PRIMARY KEY, Entry_ID INT NOT NULL UNIQUE,
 Prediction_Date DATE NOT NULL, Predicted_Wait INT NOT NULL, Best_Slot VARCHAR(11),
 CONSTRAINT fk_prediction_entry FOREIGN KEY (Entry_ID) REFERENCES Queue_Entry(Entry_ID),
 CONSTRAINT ck_prediction_wait CHECK (Predicted_Wait >= 0)
) ENGINE=InnoDB;
